import { collection, onSnapshot } from "firebase/firestore";
import { db } from "./firebase";

onSnapshot(collection(db, "users"), (snapshot) => {

    const users = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
    }));

    console.log(users);

});

1. onSnapshot():
What is it?
A Firebase function that listens for real-time changes in Firestore.
It keeps watching the database.
Whenever data changes, it automatically runs your callback function.

2. snapshot:
Every time onSnapshot() detects a change, Firebase sends you a snapshot.
A snapshot is:
A picture of the current data at that exact moment.

What is a Promise?
A promise and confirmation that the result will be available later. for example when we request to server via API to recieve data, it send promise.

What is async?
async tells JavaScript:
This function contains asynchronous work. it means it will not finish instantly, for example: baking a cake is an asyncronous task.

What is await?
await means:
Pause this function until the Promise finishes. 

useEffect(() => {
    async function loadUsers() {
        const response = await fetch("/api/users");
        const data = await response.json();
        setUsers(data);
    }
    loadUsers();
}, []);

the model is the object you use in your code to create, read, update, and delete documents in a MongoDB collection.

// Create
await User.create({ name: "Zia", age: 22 });

// Read
const users = await User.find();

// Update
await User.updateOne({ name: "Zia" }, { age: 23 });

// Delete
await User.deleteOne({ name: "Zia" });

